"""Platform authorization: deny by default, allow by role per authz-policy.json.

Roles come from the identity header set by the platform edge. The NetworkPolicy
admits traffic only from the edge, so other callers can't set the header.
Paths that aren't in canonical form are denied outright, so a rule can't be
matched by a path the application would resolve somewhere else.
"""

import json
import re
from pathlib import Path

_POLICY = json.loads((Path(__file__).parent / "authz-policy.json").read_text(encoding="utf-8"))
_HEADER = _POLICY["identity_header"].lower()
_EXEMPT = frozenset(_POLICY["exempt_paths"])
_FORBIDDEN = b'{"error":"forbidden"}'
# Every denial from this guard carries X-Platform-Authz: deny, so the release probe can tell it from an app's own 403.
_TOKEN = re.compile(r"(\*\*|\*|\{[^{}/]*\})")


def _pattern(path):
    # Captured tokens sit at odd indices, as in the Node guard; everything else is literal.
    parts = []
    for i, part in enumerate(_TOKEN.split(path)):
        if i % 2 == 0:
            parts.append(re.escape(part))
        else:
            parts.append(".*" if part == "**" else "[^/]+")
    return re.compile("".join(parts))


_RULES = [(frozenset(r["methods"]), _pattern(r["path"]), frozenset(r["roles"])) for r in _POLICY["rules"]]


def roles_from(value):
    return frozenset(part.strip() for part in (value or "").split(",") if part.strip())


def canonical(path):
    if not path.startswith("/") or "//" in path or "\\" in path:
        return False
    if any(ord(c) < 32 or ord(c) == 127 for c in path):
        return False
    return not any(segment in (".", "..") for segment in path.split("/"))


def allowed(method, path, roles, exempt_ok=True):
    if not canonical(path):
        return False
    method = "GET" if method == "HEAD" else method
    if exempt_ok and method == "GET" and path in _EXEMPT:
        return True
    return any(method in methods and pattern.fullmatch(path) and roles & rule_roles for methods, pattern, rule_roles in _RULES)


class AuthzASGI:
    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope["type"] not in ("http", "websocket"):
            return await self.app(scope, receive, send)
        values = [v.decode("latin-1") for k, v in scope["headers"] if k.decode("latin-1").lower() == _HEADER]
        roles = roles_from(values[0]) if len(values) == 1 else frozenset()
        if allowed(scope.get("method", "GET"), scope["path"], roles, exempt_ok=scope["type"] == "http"):
            return await self.app(scope, receive, send)
        if scope["type"] == "websocket":
            await receive()
            await send({"type": "websocket.close", "code": 1008})
            return
        await send({"type": "http.response.start", "status": 403, "headers": [(b"content-type", b"application/json"), (b"x-platform-authz", b"deny")]})
        await send({"type": "http.response.body", "body": _FORBIDDEN})


class AuthzWSGI:
    def __init__(self, app):
        self.app = app
        self._environ_key = "HTTP_" + _HEADER.upper().replace("-", "_")

    def __call__(self, environ, start_response):
        roles = roles_from(environ.get(self._environ_key))
        if allowed(environ["REQUEST_METHOD"], environ.get("PATH_INFO", "/"), roles):
            return self.app(environ, start_response)
        start_response("403 Forbidden", [("Content-Type", "application/json"), ("X-Platform-Authz", "deny")])
        return [_FORBIDDEN]
